nextflow_process {
    name "Test Process BEDTOOLS_GENOMECOV"
    script "../main.nf"
    process "BEDTOOLS_GENOMECOV"
    config "./nextflow.config"

    tag "modules"
    tag "modules_nfcore"
    tag "bedtools"
    tag "bedtools/genomecov"

    test("sarscov2 - no scale") {
        when {
            process {
                """
                input[0] = [
                    [ id:'test' ], // meta map
                    file(params.modules_testdata_base_path + "genomics/sarscov2/illumina/bam/test.paired_end.bam", checkIfExists: true),
                    1
                ]
                // sizes
                input[1] = []
                // extension
                input[2] = "txt"
                input[3] = true
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(process.out).match() }
            )
        }
    }

    test("sarscov2 - dummy sizes") {
        when {
            process {
                """
                input[0] = [
                    [ id:'test'],
                    file(params.modules_testdata_base_path + "genomics/sarscov2/illumina/bam/test.paired_end.bam", checkIfExists: true),
                    0.5
                ]
                // sizes
                input[1] = file('dummy_chromosome_sizes')
                // extension
                input[2] = 'txt'
                input[3] = false
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(process.out).match() }
            )
        }
    }

    test("sarscov2 - scale") {
        when {
            process {
                """
                input[0] = [
                    [ id:'test'],
                    file(params.modules_testdata_base_path + "genomics/sarscov2/genome/bed/baits.bed", checkIfExists: true),
                    0.5
                ]
                // sizes
                input[1] = file(params.modules_testdata_base_path + "genomics/sarscov2/genome/genome.sizes", checkIfExists: true)
                // extension
                input[2] = 'txt'
                input[3] = false
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(process.out).match() }
            )
        }
    }

